//packages/content-engine/src/firebase/runJob.ts
import { onRequest } from 'firebase-functions/v2/https';
import { getApps, initializeApp } from 'firebase-admin/app';
import { getFirestore } from 'firebase-admin/firestore';
import { getStrategy } from '../registry/strategies.js';
import { resolveEngineConfig } from '../registry/resolve.js';
const getAdminDb = () => {
    if (getApps().length === 0)
        initializeApp();
    return getFirestore();
};
const asGenerateInput = (payload) => {
    if (!payload || typeof payload !== 'object')
        return {};
    return payload;
};
export const runJob = onRequest({ region: 'asia-northeast1' }, async (_req, res) => {
    const db = getAdminDb();
    const now = Date.now();
    // ref を外に出して、例外時にも error 終端できるようにする
    let ref = null;
    let runId = null;
    try {
        const snap = await db
            .collection('runs')
            .where('status', '==', 'queued')
            .orderBy('createdAt', 'asc')
            .limit(1)
            .get();
        if (snap.empty) {
            res.status(200).json({ ok: true, processed: 0, now });
            return;
        }
        const doc = snap.docs[0];
        ref = doc.ref;
        runId = doc.id;
        // queued → processing（競合対策）
        const runData = await db.runTransaction(async (tx) => {
            const cur = await tx.get(doc.ref);
            const data = (cur.data() ?? {});
            if (data.status !== 'queued')
                return null;
            tx.update(doc.ref, {
                status: 'processing',
                startedAt: data.startedAt ?? now,
                updatedAt: now,
                error: '',
            });
            return data;
        });
        if (!runData) {
            res.status(200).json({ ok: true, processed: 0, now, skipped: true });
            return;
        }
        const strategyIdRaw = runData.strategyId ?? '';
        const payloadPartial = asGenerateInput(runData.payload);
        // 1) current.activePresetId を毎回読む（判断の反映点）
        const configSnap = await db.collection('contentEngineConfig').doc('current').get();
        const configData = configSnap.exists
            ? configSnap.data()
            : undefined;
        const activePresetId = configData?.activePresetId && configData.activePresetId.trim()
            ? configData.activePresetId.trim()
            : null;
        // 2) payload.presetId（任意）→ activePresetId → undefined の順
        const payloadPresetId = typeof payloadPartial.presetId === 'string'
            ? (payloadPartial.presetId ?? '').trim()
            : '';
        const presetId = payloadPresetId || activePresetId || undefined;
        const resolved = resolveEngineConfig({
            presetId,
            strategyId: strategyIdRaw || undefined,
            sourceId: payloadPartial.sourceId,
            channelId: payloadPartial.channelId,
        });
        const strategy = getStrategy(resolved.strategyId);
        if (!strategy) {
            const msg = `Strategy not found: "${resolved.strategyId}". Available: (${[]})`;
            await doc.ref.update({
                status: 'error',
                finishedAt: Date.now(),
                updatedAt: Date.now(),
                error: msg,
                result: null,
                resolved: {
                    strategyId: resolved.strategyId,
                    sourceId: resolved.sourceId,
                    channelId: resolved.channelId,
                    presetId: resolved.presetId ?? '',
                    warnings: resolved.warnings,
                },
            });
            res.status(200).json({ ok: false, processed: 1, runId, error: msg, now: Date.now() });
            return;
        }
        const input = {
            topic: payloadPartial.topic ?? 'テスト記事',
            draft: payloadPartial.draft,
            sourceId: resolved.sourceId,
            channelId: resolved.channelId,
        };
        const result = await strategy.generate(input);
        await doc.ref.update({
            status: 'success',
            finishedAt: Date.now(),
            updatedAt: Date.now(),
            error: '',
            result,
            resolved: {
                strategyId: resolved.strategyId,
                sourceId: resolved.sourceId,
                channelId: resolved.channelId,
                presetId: resolved.presetId ?? '',
                warnings: resolved.warnings,
            },
        });
        res.status(200).json({
            ok: true,
            processed: 1,
            runId,
            strategyId: resolved.strategyId,
            resolvedPresetId: resolved.presetId ?? '',
            warnings: resolved.warnings,
            title: result.title,
            now: Date.now(),
        });
    }
    catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        // ✅ ここが「processingで止まらない」本体：ref が分かってるなら error 終端
        if (ref) {
            try {
                await ref.update({
                    status: 'error',
                    finishedAt: Date.now(),
                    updatedAt: Date.now(),
                    error: msg,
                    result: null,
                });
            }
            catch {
                // best-effort
            }
        }
        res.status(500).json({ ok: false, runId, error: msg, now: Date.now() });
    }
});
